		[75412] = {
			cn_trad = "1、玩家角色必須達到<font color='#00D50f'>85級</font>才可參與<font color='#d736ff'>滅世魔拳·雷頓</font>的試煉<br/>2、BOSS刷新後，每人可以免費挑戰<font color='#00D50f'>3次</font><font color='#d736ff'>滅世魔拳·雷頓</font><br/>3、BOSS刷新的當天<font color='#00D50f'>10點</font>到<font color='#00D50f'>22點</font>開放挑戰<br/>4、活動當天對BOSS造成的傷害會累計排行榜，<font color='#00D50f'>22點</font>按照對BOSS造成的總傷害排名發放獎勵<br/>5、獎勵獲得的浮空戰令可以在<font color='#d736ff'>浮空商城</font>兌換各種道具<br/>6、根據全服的傷害累計值，發放該檔位下的全服獎勵。<br/>7、購買增加的挑戰次數僅限活動當日使用。",
		},
		[75413] = {
			cn_trad = "每週三10點-22點開啟挑戰，24點關閉",
